/**
 * International dial codes, keyed by ISO 3166-1 alpha-2.
 *
 * Deliberately *not* the `/countries` lookup: that list is the verification countries an operator
 * has configured, which is a handful of entries. A contact person can be reached anywhere, so the
 * dial-code picker needs the full set.
 *
 * Only the code and the prefix are stored here. Display names come from `Intl.DisplayNames` in the
 * page's own language, so the list is translated for every locale the app ships without carrying
 * ten copies of two hundred country names. `englishName` is the fallback for the rare runtime that
 * cannot resolve a region, and it stays searchable in every locale — someone typing "Egypt" on the
 * Arabic page still finds مصر.
 */
export interface PhoneCountry {
  /** ISO 3166-1 alpha-2, uppercase. Drives both the flag and what the server stores. */
  code: string;
  /** International dial prefix, including the leading plus. */
  dialCode: string;
  englishName: string;
}

