/** Egypt is the platform's home market, so it is what the picker opens on. */
export const DEFAULT_PHONE_COUNTRY = 'EG';

const BY_CODE = new Map(PHONE_COUNTRIES.map((country) => [country.code, country]));

export function findPhoneCountry(code: string | undefined): PhoneCountry | undefined {
  return code ? BY_CODE.get(code.toUpperCase()) : undefined;
}

/**
 * The flag as a URL, per flagcdn.com's `w{width}/{iso-lower}.png` scheme. Rendered at 20px with a
 * 40px source for high-density screens.
 */
export function flagUrl(code: string, width: 20 | 40 = 20): string {
  return `https://flagcdn.com/w${width}/${code.toLowerCase()}.png`;
}
